begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.ki(t text) returns uuid language sql immutable as $$select md5('kids-k2-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.ki(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)
select pg_temp.ki(x),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',x||'-k2@example.invalid',now(),now(),now() from unnest(array['owner','teacher','reception','other','teacher2']) x;
insert into public.organizations(id,name,slug,status) values(pg_temp.ki('org'),'Kids K2 fictício','kids-k2-test','active'),(pg_temp.ki('foreign'),'Outro fictício','kids-k2-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.ki('unit'),pg_temp.ki('org'),'Sede fictícia K2','sede','headquarters'),(pg_temp.ki('otherunit'),pg_temp.ki('org'),'Filial fictícia','filial','campus'),(pg_temp.ki('foreignunit'),pg_temp.ki('foreign'),'Outra','outra','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,role,status,default_unit_id)
select pg_temp.ki(x||'-membership'),pg_temp.ki('org'),pg_temp.ki(x),case when x='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active',pg_temp.ki('unit') from unnest(array['owner','teacher','reception','other','teacher2']) x;
insert into public.membership_unit_access(membership_id,unit_id,access_level) select pg_temp.ki(x||'-membership'),pg_temp.ki('unit'),'read' from unnest(array['teacher','reception','teacher2']) x;
insert into public.people(id,organization_id,unit_id,full_name,birth_date,status,auth_user_id)
select pg_temp.ki(x||'-person'),pg_temp.ki('org'),pg_temp.ki('unit'),x||' pessoa fictícia',current_date-interval '35 years','active',pg_temp.ki(x) from unnest(array['owner','teacher','reception','teacher2']) x;
insert into public.people(id,organization_id,unit_id,full_name,birth_date,status) values
(pg_temp.ki('child'),pg_temp.ki('org'),pg_temp.ki('unit'),'Criança K2 fictícia',current_date-interval '7 years','active'),
(pg_temp.ki('child2'),pg_temp.ki('org'),pg_temp.ki('unit'),'Criança K2 segunda',current_date-interval '8 years','active'),
(pg_temp.ki('adult'),pg_temp.ki('org'),pg_temp.ki('unit'),'Adulto autorizado fictício',current_date-interval '38 years','active');
insert into private.kids_profiles(id,organization_id,unit_id,person_id,review_status,created_by) select pg_temp.ki(x||'-profile'),pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki(x),'approved',pg_temp.ki('owner') from unnest(array['child','child2']) x;
insert into private.kids_guardians(id,organization_id,unit_id,profile_id,person_id,relationship,verification_note,can_pickup,status,approved_by,approved_at,created_by) select pg_temp.ki(x||'-guardian'),pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki(x||'-profile'),pg_temp.ki('adult'),'Responsável','Conferido em teste fictício',true,'approved',pg_temp.ki('owner'),now(),pg_temp.ki('owner') from unnest(array['child','child2']) x;
insert into private.kids_care(profile_id,organization_id,unit_id,instructions,source) values(pg_temp.ki('child-profile'),pg_temp.ki('org'),pg_temp.ki('unit'),'Orientação K2 restrita fictícia','Responsável fictício');
create function pg_temp.op(a text,i text,v integer,d jsonb) returns jsonb language sql as $$select public.kids_operations_save(pg_temp.ki('org'),pg_temp.ki('unit'),extensions.gen_random_uuid(),a,pg_temp.ki(i),v,d)$$;
create function pg_temp.page(s text default 'session') returns jsonb language sql as $$select public.kids_operations_page(pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki(s),null,'','all')$$;
create function pg_temp.entry(child text default 'child',grp text default 'group') returns jsonb language sql as $$select jsonb_build_object('sessionId',pg_temp.ki('session'),'groupId',pg_temp.ki(grp),'profileId',pg_temp.ki(child||'-profile'),'guardianId',pg_temp.ki('adult'),'identityConfirmed',true,'receiptSecret',repeat('a',64))$$;
create function pg_temp.exit_data(code text default repeat('a',64)) returns jsonb language sql as $$select jsonb_build_object('guardianId',pg_temp.ki('adult'),'identityConfirmed',true,'receiptSecret',code)$$;
select ok(not has_function_privilege('anon','public.kids_operations_save(uuid,uuid,uuid,text,uuid,integer,jsonb)','execute'),'visitante não opera');
select ok(not has_function_privilege('service_role','private.kids_operations_save(uuid,uuid,uuid,text,uuid,integer,jsonb)','execute'),'serviço não pula operação');
select ok(not has_table_privilege('authenticated','private.kids_attendance','insert') and not has_table_privilege('authenticated','private.kids_custody_events','delete'),'presença e histórico sem acesso direto');
select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relkind='r' and c.relname like 'kids_%'),'RLS em todo Kids');
set local role authenticated;
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.op('room','room',0,'{"name":"Sala A","location":"Térreo","capacity":1,"active":true}')$$,'cria sala');
select lives_ok($$select pg_temp.op('room','room2',0,'{"name":"Sala B","location":"Térreo","capacity":2,"active":true}')$$,'cria segunda sala');
select lives_ok($$select pg_temp.op('class','class',0,'{"name":"Crianças","minMonths":60,"maxMonths":143,"active":true}')$$,'cria turma');
select throws_ok($$select pg_temp.op('room','room',0,'{"name":"Sobrescrever","location":"","capacity":4,"active":true}')$$,'40001','kids_version_conflict','versão protege edição');
select lives_ok($$select pg_temp.op('session','session',0,jsonb_build_object('name','Encontro K2','startsAt',now()-interval '5 minutes','endsAt',now()+interval '2 hours'))$$,'cria sessão');
select throws_ok($$select pg_temp.op('sessionState','session',1,'{"status":"open"}')$$,'22023','kids_session_not_ready','sem salas não abre');
select lives_ok($$select pg_temp.op('group','group',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'roomId',pg_temp.ki('room'),'classId',pg_temp.ki('class'),'capacity',1,'minStaff',1))$$,'vincula sala');
select lives_ok($$select pg_temp.op('group','group2',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'roomId',pg_temp.ki('room2'),'classId',pg_temp.ki('class'),'capacity',2,'minStaff',1))$$,'vincula destino');
select throws_ok($$select pg_temp.op('sessionState','session',1,'{"status":"open"}')$$,'22023','kids_staff_insufficient','sem equipe não abre');
select throws_ok($$select pg_temp.op('assignment','bad-assignment',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'personId',pg_temp.ki('adult'),'groupId',pg_temp.ki('group'),'role','teacher','canCare',true,'active',true))$$,'22023','kids_staff_identity_required','não escala adulto sem conta vinculada');
select lives_ok($$select pg_temp.op('assignment','teacher-assignment',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'personId',pg_temp.ki('teacher-person'),'groupId',pg_temp.ki('group'),'role','teacher','canCare',false,'active',true))$$,'escala professor');
select throws_ok($$select pg_temp.op('assignment','duplicate-assignment',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'personId',pg_temp.ki('teacher-person'),'groupId',pg_temp.ki('group2'),'role','teacher','canCare',false,'active',true))$$,'40001','kids_staff_overlap','não conta pessoa em duas salas');
select lives_ok($$select pg_temp.op('assignment','teacher2-assignment',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'personId',pg_temp.ki('teacher2-person'),'groupId',pg_temp.ki('group2'),'role','teacher','canCare',true,'active',true))$$,'escala destino');
select lives_ok($$select pg_temp.op('assignment','reception-assignment',0,jsonb_build_object('sessionId',pg_temp.ki('session'),'personId',pg_temp.ki('reception-person'),'groupId',null,'role','reception','canCare',false,'active',true))$$,'escala recepção');
select lives_ok($$select pg_temp.op('sessionState','session',1,'{"status":"open"}')$$,'abre sessão equipada');
select is(pg_temp.page()->'groups'->0->>'occupied','0','sala começa vazia');
select throws_ok($$select pg_temp.op('room','room',1,'{"name":"Alterar aberta","location":"","capacity":2,"active":true}')$$,'40001','kids_room_in_use','não muda sala em uso');
select throws_ok($$select pg_temp.op('checkin','attendance',0,pg_temp.entry()||'{"identityConfirmed":false}')$$,'42501','kids_guardian_required','exige conferência presencial');
select lives_ok($$select public.kids_operations_save(pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki('entry-request'),'checkin',pg_temp.ki('attendance'),0,pg_temp.entry())$$,'entrada confirmada');
select lives_ok($$select public.kids_operations_save(pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki('entry-request'),'checkin',pg_temp.ki('attendance'),0,pg_temp.entry())$$,'retry não duplica entrada');
select throws_ok($$select pg_temp.op('checkin','full-attendance',0,pg_temp.entry('child2'))$$,'40001','kids_capacity_full','capacidade impede segunda entrada');
select throws_ok($$select pg_temp.op('checkin','duplicate-attendance',0,pg_temp.entry('child','group2'))$$,'23505',null,'criança não ocupa duas salas');
select throws_ok($$select pg_temp.op('sessionState','session',2,'{"status":"closed"}')$$,'40001','kids_children_present','não encerra com crianças');
select ok(not (pg_temp.page()::text like '%receipt_hash%' or pg_temp.page()::text like '%'||repeat('a',64)||'%'),'consulta não expõe segredo ou hash');
select pg_temp.actor('reception');
select is((pg_temp.page()->'items'->0->'care'),'null'::jsonb,'recepção não recebe saúde');
select is(jsonb_array_length(pg_temp.page()->'items'->0->'guardians'),1,'recepção vê adultos vigentes');
select is(jsonb_array_length(public.kids_admission_choices(pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki('session'),'Criança')->'items'),1,'busca exclui presentes');
select is((pg_temp.op('checkout','attendance',1,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts'),'4','código errado conta tentativa');
select is((pg_temp.op('checkout','attendance',2,pg_temp.exit_data(repeat('c',64)))->>'ok'),'false','código de outro atendimento não retira');
select throws_ok($$select pg_temp.op('recover','attendance',3,pg_temp.exit_data(repeat('d',64))||'{"reason":"Conferência assistida de teste fictício"}')$$,'42501','kids_access_denied','recepção não recupera código');
select pg_temp.actor('teacher');
select is(jsonb_array_length(pg_temp.page()->'items'),1,'professor vê sala própria');
select is(pg_temp.page()->'items'->0->'care','null'::jsonb,'professor sem consentimento não vê cuidado');
select is(jsonb_array_length(pg_temp.page()->'items'->0->'guardians'),0,'professor não recebe responsáveis');
select throws_ok($$select pg_temp.op('checkout','attendance',3,pg_temp.exit_data())$$,'42501','kids_access_denied','professor não faz retirada');
select pg_temp.actor('teacher2');
select is(jsonb_array_length(pg_temp.page()->'items'),0,'outra sala não recebe criança');
select pg_temp.actor('other');
select throws_ok($$select pg_temp.page()$$,'42501','kids_access_denied','conta não escalada não consulta');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.op('hold','attendance',3,'{"hold":true,"reason":"Conferência adicional fictícia"}')$$,'supervisão protege retirada');
select throws_ok($$select pg_temp.op('checkout','attendance',4,pg_temp.exit_data())$$,'40001','kids_hold_or_transfer_pending','proteção bloqueia saída');
select lives_ok($$select pg_temp.op('hold','attendance',4,'{"hold":false,"reason":"Conferência concluída fictícia"}')$$,'remove proteção com motivo');
select lives_ok($$select pg_temp.op('recover','attendance',5,pg_temp.exit_data(repeat('d',64))||'{"reason":"Responsável novamente conferido em teste fictício"}')$$,'recupera sem retirar');
select is(pg_temp.page()->'items'->0->>'status','present','recuperação não retira');
select is(pg_temp.op('checkout','attendance',6,pg_temp.exit_data())->>'ok','false','código antigo invalidado');
select lives_ok($$select pg_temp.op('transfer','attendance',7,jsonb_build_object('targetGroupId',pg_temp.ki('group2'),'reason','Recebimento acompanhado fictício'))$$,'solicita transferência');
select throws_ok($$select pg_temp.op('checkout','attendance',8,pg_temp.exit_data(repeat('d',64)))$$,'40001','kids_hold_or_transfer_pending','transferência pendente bloqueia retirada');
select pg_temp.actor('teacher2');
select is(pg_temp.page()->'items'->0->'care','null'::jsonb,'destino não vê cuidado antes de receber');
select lives_ok($$select pg_temp.op('transferAccept','attendance',8,'{}')$$,'destino confirma recebimento');
select is(pg_temp.page()->'items'->0->>'care','Orientação K2 restrita fictícia','destino autorizado vê cuidado após recebimento');
select pg_temp.actor('teacher');
select is(jsonb_array_length(pg_temp.page()->'items'),0,'origem deixa de visualizar criança transferida');
reset role;
select is((select occupied from private.kids_session_rooms where id=pg_temp.ki('group')),0,'origem libera vaga');
select is((select occupied from private.kids_session_rooms where id=pg_temp.ki('group2')),1,'destino ocupa uma vaga');
select throws_ok($$update private.kids_profiles set status='archived' where id=pg_temp.ki('child-profile')$$,'42501','kids_child_present','não arquiva criança presente');
select throws_ok($$update public.people set unit_id=pg_temp.ki('otherunit') where id=pg_temp.ki('child')$$,'42501','kids_child_present','não transfere unidade com presença');
update private.kids_guardians set status='revoked',approved_by=null,approved_at=null where profile_id=pg_temp.ki('child-profile');
set local role authenticated;select pg_temp.actor('owner');
select throws_ok($$select pg_temp.op('checkout','attendance',9,pg_temp.exit_data(repeat('d',64)))$$,'42501','kids_guardian_required','revogação após entrada impede saída');
reset role;update private.kids_guardians set status='approved',approved_by=pg_temp.ki('owner'),approved_at=now() where profile_id=pg_temp.ki('child-profile');
set local role authenticated;select pg_temp.actor('reception');
select lives_ok($$select pg_temp.op('checkout','attendance',9,pg_temp.exit_data(repeat('d',64)))$$,'retira com autorização atual e código novo');
select throws_ok($$select pg_temp.op('checkout','attendance',9,pg_temp.exit_data(repeat('d',64)))$$,'40001','kids_version_conflict','não retira duas vezes');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.op('checkin','attendance2',0,pg_temp.entry('child2'))$$,'nova criança ocupa vaga liberada');
select is(pg_temp.op('checkout','attendance2',1,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts','4','tentativa 1');
select is(pg_temp.op('checkout','attendance2',2,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts','3','tentativa 2');
select is(pg_temp.op('checkout','attendance2',3,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts','2','tentativa 3');
select is(pg_temp.op('checkout','attendance2',4,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts','1','tentativa 4');
select is(pg_temp.op('checkout','attendance2',5,pg_temp.exit_data(repeat('b',64)))->>'remainingAttempts','0','tentativa 5');
select throws_ok($$select pg_temp.op('checkout','attendance2',6,pg_temp.exit_data())$$,'40001','kids_receipt_recovery_required','limite exige recuperação mesmo com código certo');
select lives_ok($$select pg_temp.op('recover','attendance2',6,pg_temp.exit_data(repeat('e',64))||'{"reason":"Conferência assistida após tentativas fictícias"}')$$,'supervisão recupera após limite');
reset role;
update private.kids_attendance set receipt_expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.ki('attendance2');
set local role authenticated;select pg_temp.actor('owner');
select throws_ok($$select pg_temp.op('checkout','attendance2',7,pg_temp.exit_data(repeat('e',64)))$$,'40001','kids_receipt_recovery_required','código expirado não retira');
select lives_ok($$select pg_temp.op('recover','attendance2',7,pg_temp.exit_data(repeat('f',64))||'{"reason":"Conferência assistida após expiração fictícia"}')$$,'recupera após expiração');
select lives_ok($$select pg_temp.op('checkout','attendance2',8,pg_temp.exit_data(repeat('f',64)))$$,'retirada da segunda criança');
select lives_ok($$select pg_temp.op('sessionState','session',2,'{"status":"closed"}')$$,'encerra após todas retiradas');
select throws_ok($$select pg_temp.op('sessionState','session',3,'{"status":"open"}')$$,'22023','kids_invalid','não reabre sessão encerrada');
select throws_ok($$select public.kids_operations_page(pg_temp.ki('foreign'),pg_temp.ki('foreignunit'))$$,'42501','kids_access_denied','não acessa outro ministério');
reset role;
select is((select count(*)::integer from private.kids_attendance where profile_id=pg_temp.ki('child-profile')),1,'presença única');
select is((select occupied from private.kids_session_rooms where id=pg_temp.ki('group2')),0,'saída libera vaga');
select is((select count(*)::integer from private.kids_custody_events where attendance_id=pg_temp.ki('attendance') and action='checkin'),1,'retry não duplica histórico');
select ok(not exists(select 1 from private.kids_operation_requests where result::text like '%'||repeat('d',64)||'%'),'replay não guarda segredo');
select ok(not exists(select 1 from private.kids_custody_events where details::text like '%Orientação K2%' or details::text like '%'||repeat('a',64)||'%'),'histórico não replica cuidado nem código');
update auth.users set email_confirmed_at=null where id=pg_temp.ki('reception');
set local role authenticated;select pg_temp.actor('reception');
select throws_ok($$select pg_temp.page()$$,'42501','self_service_identity_unavailable','conta sem confirmação não consulta');
reset role;
update auth.users set email_confirmed_at=now() where id=pg_temp.ki('reception');
delete from public.membership_unit_access where membership_id=pg_temp.ki('teacher-membership');
set local role authenticated;select pg_temp.actor('teacher');
select throws_ok($$select pg_temp.page()$$,'42501','kids_access_denied','perda do escopo da igreja bloqueia professor');
select pg_temp.actor('owner');
select throws_ok($$select public.kids_operations_page(pg_temp.ki('org'),pg_temp.ki('otherunit'),pg_temp.ki('session'))$$,'42501','kids_access_denied','sessão de outra unidade não é aceita nem pela gestão');
reset role;
update public.organization_units set status='suspended' where id=pg_temp.ki('unit');
set local role authenticated;
select throws_ok($$select pg_temp.page()$$,'42501','kids_access_denied','unidade suspensa não consulta operação');
reset role;
update public.organization_units set status='active' where id=pg_temp.ki('unit');
insert into public.saas_unit_contracts(organization_id,unit_id,payer_unit_id,plan_id,status,module_decisions) values(pg_temp.ki('org'),pg_temp.ki('unit'),pg_temp.ki('unit'),'plan-essential','active','{"kids":false,"people":true}');
set local role authenticated;
select throws_ok($$select pg_temp.page()$$,'42501','kids_access_denied','bloqueio contratual não é contornado pela operação');
reset role;
select * from finish();
rollback;
